   "source": [
    "CREATE OR REPLACE VIEW gold.analistas.vw_superset_paretodedefeitoscontagem AS (\n",
    "\n",
    "WITH \n",
    "\n",
    "-- 1. Dimensão de SKU com mapeamento completo de famílias e subgrupos\n",
    "SKU_ATRIBUTOS AS (\n",
    "    SELECT \n",
    "        P.CodProduto, \n",
    "        P.DescricaoProduto, \n",
    "        P.Marca AS Fornecedor, \n",
    "        P.ModeloMkt AS Modelo,\n",
    "        GP.NomeGrupoPai AS Familia, \n",
    "        GP.LinhaDeNegocio, \n",
    "        GP.NomeGrupoFamilia, \n",
    "        P.UsadoComo\n",
    "    FROM gold.sankhya.dim_produtos P\n",
    "    INNER JOIN gold.sankhya.dim_grupo_produtos GP \n",
    "        ON GP.CodGrupoProduto = P.CodGrupoProduto\n",
    "    WHERE (\n",
    "        (P.UsadoComo IN ('Venda (fabricação própria)', 'Revenda')\n",
    "         AND GP.LinhaDeNegocio IN ('WordPC/Skill')\n",
    "         AND (GP.NomeGrupoPai <> 'COMPONENTES' OR UPPER(P.DescricaoProduto) LIKE '%GABINETE%'))\n",
    "        OR UPPER(P.DescricaoProduto) LIKE '%GABINETE%'\n",
    "    )\n",
    "),\n",
    "\n",
    "-- 2A. Reparos 2025 (fato_sintoma_serie + dimensões assistência técnica)\n",
    "BASE_REPAROS_2025 AS (\n",
    "    SELECT\n",
    "        fs.OrdemProducao,\n",
    "        pa.CodProdutoAcabado                                            AS CodProd,\n",
    "        CAST(fs.DataApontamento AS DATE)                                AS Data_Reparo,\n",
    "        fs.DataApontamento                                              AS DataHora_Reparo,\n",
    "        YEAR(fs.DataApontamento)                                       AS Ano,\n",
    "        MONTH(fs.DataApontamento)                                      AS Mes,\n",
    "        WEEKOFYEAR(fs.DataApontamento)                                 AS Semana,\n",
    "        COALESCE(NULLIF(TRIM(UPPER(dat.Defeito)), ''), 'SEM DEFEITO INFORMADO') AS Defeito_Estratificado,\n",
    "        COALESCE(NULLIF(TRIM(UPPER(dr.Descricao)), ''), 'SEM SINTOMA INFORMADO') AS Sintoma,\n",
    "        COALESCE(NULLIF(TRIM(UPPER(aat.Acao)), ''), 'SEM AÇÃO REGISTRADA') AS Acao_Corretiva,\n",
    "        CASE WHEN fs.CodigProdutoBelMicro > 0 THEN fs.CodigProdutoBelMicro END AS CodPecaTrocada,\n",
    "        COALESCE(\n",
    "            CASE WHEN fs.CodigProdutoBelMicro > 0 THEN NULLIF(TRIM(comp.DescricaoProduto), '') END,\n",
    "            'NENHUMA PEÇA TROCADA'\n",
    "        ) AS DescricaoPecaTrocada,\n",
    "        1                                                               AS Qtd_Defeitos,\n",
    "        COALESCE(NULLIF(TRIM(fs.SerieProdutoAcabado), ''), 'S/N')      AS Serie_PA,\n",
    "        COALESCE(\n",
    "            fs.Origem || ' - LINHA ' || CAST(fs.LinhaDoApontamento AS STRING),\n",
    "            'NÃO INFORMADO'\n",
    "        ) AS Centro_Trabalho_Reparo\n",
    "    FROM gold.sankhya.fato_sintoma_serie fs\n",
    "    INNER JOIN gold.sankhya.fato_ordem_producao_seriepa pa\n",
    "        ON fs.SerieProdutoAcabado = pa.SerieProdutoAcabado\n",
    "    LEFT JOIN gold.sankhya.dim_defeito_runin dr\n",
    "        ON fs.NumeroDefeito = dr.NumeroDefeito\n",
    "    LEFT JOIN gold.sankhya.dim_defeito_assistencia_tecnica dat\n",
    "        ON fs.CodDefeito = dat.CodDefeito\n",
    "    LEFT JOIN gold.sankhya.dim_acao_assistencia_tecnica aat\n",
    "        ON fs.CodAcao = aat.CodAcao\n",
    "    LEFT JOIN gold.sankhya.dim_produtos comp\n",
    "        ON fs.CodigProdutoBelMicro = comp.CodProduto\n",
    "    WHERE fs.DataAlteracaoReparo IS NOT NULL\n",
    "      AND fs.DataApontamento >= '2025-01-01'\n",
    "      AND fs.DataApontamento < '2026-01-01'\n",
    "      AND pa.CodProdutoAcabado <> 85273\n",
    "),\n",
    "\n",
    "-- 2B. Reparos 2026 (fato_producao_reparo_cabecalho + item)\n",
    "BASE_REPAROS_2026 AS (\n",
    "    SELECT\n",
    "        cab.OrdemProducao,\n",
    "        cab.CodProdutoAcabado                                           AS CodProd,\n",
    "        CAST(cab.DataHoraInicioReparo AS DATE)                          AS Data_Reparo,\n",
    "        cab.DataHoraInicioReparo                                        AS DataHora_Reparo,\n",
    "        YEAR(cab.DataHoraInicioReparo)                                 AS Ano,\n",
    "        MONTH(cab.DataHoraInicioReparo)                                AS Mes,\n",
    "        WEEKOFYEAR(cab.DataHoraInicioReparo)                           AS Semana,\n",
    "        COALESCE(NULLIF(TRIM(UPPER(def.DescricaoDefeito)), ''), 'SEM DEFEITO INFORMADO') AS Defeito_Estratificado,\n",
    "        COALESCE(NULLIF(TRIM(UPPER(sint.DescricaoSintoma)), ''), 'SEM SINTOMA INFORMADO') AS Sintoma,\n",
    "        COALESCE(NULLIF(TRIM(UPPER(acao.DescricaoAcaoCorretiva)), ''), 'SEM AÇÃO REGISTRADA') AS Acao_Corretiva,\n",
    "        item.CodMateriaPrima                                            AS CodPecaTrocada,\n",
    "        COALESCE(NULLIF(TRIM(prod_peca.DescricaoProduto), ''), 'NENHUMA PEÇA TROCADA') AS DescricaoPecaTrocada,\n",
    "        1                                                               AS Qtd_Defeitos,\n",
    "        COALESCE(NULLIF(TRIM(cab.SerieProdutoAcabado), ''), 'S/N')     AS Serie_PA,\n",
    "        COALESCE(NULLIF(TRIM(pt_rep.DescricaoPosto), ''), CAST(cab.CodCentroTrabalho AS STRING)) AS Centro_Trabalho_Reparo\n",
    "    FROM gold.sankhya.fato_producao_reparo_cabecalho cab\n",
    "    INNER JOIN gold.sankhya.fato_producao_reparo_item item \n",
    "        ON cab.CodLancamentoReparo = item.CodLancamentoReparo\n",
    "    LEFT JOIN gold.sankhya.dim_produtos prod_peca \n",
    "        ON item.CodMateriaPrima = prod_peca.CodProduto\n",
    "    LEFT JOIN gold.sankhya.dim_posto_trabalho pt_rep \n",
    "        ON cab.CodCentroTrabalho = pt_rep.CodCentroTrabalho\n",
    "    LEFT JOIN gold.sankhya.dim_producao_sintoma_reparo sint \n",
    "        ON cab.CodSintoma = sint.CodSintoma\n",
    "    LEFT JOIN gold.sankhya.dim_producao_defeito_reparo def \n",
    "        ON item.CodDefeito = def.CodDefeito\n",
    "    LEFT JOIN gold.sankhya.dim_producao_acao_reparo acao \n",
    "        ON item.CodAcaoCorretiva = acao.CodAcaoCorretiva\n",
    "    WHERE cab.StatusReparo = 'Concluído'\n",
    "      AND cab.DataHoraInicioReparo >= '2026-01-01'\n",
    "      AND cab.CodProdutoAcabado <> 85273\n",
    "),\n",
    "\n",
    "-- 2C. União dos dois anos com colunas idênticas\n",
    "BASE_REPAROS_GRANULAR AS (\n",
    "    SELECT * FROM BASE_REPAROS_2025\n",
    "    UNION ALL\n",
    "    SELECT * FROM BASE_REPAROS_2026\n",
    "),\n",
    "\n",
    "-- 3. Aplica todos os filtros de negócio ANTES de calcular o Pareto (garante ranking dinâmico = volume real)\n",
    "REPAROS_FILTRADOS AS (\n",
    "    SELECT r.*, sku.Familia, COALESCE(pp.DescricaoProcesso, 'HISTORICO 2025') AS Processo\n",
    "    FROM BASE_REPAROS_GRANULAR r\n",
    "    INNER JOIN SKU_ATRIBUTOS sku ON r.CodProd = sku.CodProduto\n",
    "    LEFT JOIN gold.sankhya.fato_ordem_producao fop ON r.OrdemProducao = fop.OrdemProducao\n",
    "    LEFT JOIN gold.sankhya.dim_processo_producao pp ON fop.CodProcessoUnico = pp.CodProcessoUnico\n",
    "    WHERE r.Data_Reparo <= CURRENT_DATE()\n",
    "      AND r.CodProd <> 85273\n",
    "      AND (pp.DescricaoProcesso IN ('2 - COMPUTADORES MAESTRO PLUS', '6 - MONITOR MAESTRO PLUS') OR pp.DescricaoProcesso IS NULL)\n",
    "),\n",
    "\n",
    "-- 4. Rankings DINÂMICOS: calculados sobre o resultado filtrado → sempre do maior para o menor volume\n",
    "AGREGADO_SINTOMA AS (\n",
    "    SELECT Ano, Mes, Sintoma, SUM(Qtd_Defeitos) AS Total_Sintoma\n",
    "    FROM REPAROS_FILTRADOS\n",
    "    GROUP BY Ano, Mes, Sintoma\n",
    "),\n",
    "PARETO_SINTOMA AS (\n",
    "    SELECT \n",
    "        Ano,\n",
    "        Mes,\n",
    "        Sintoma,\n",
    "        ROW_NUMBER() OVER (PARTITION BY Ano, Mes ORDER BY Total_Sintoma DESC, Sintoma ASC) AS Rank_Sintoma,\n",
    "        SUM(Total_Sintoma) OVER (\n",
    "            PARTITION BY Ano, Mes\n",
    "            ORDER BY Total_Sintoma DESC, Sintoma ASC\n",
    "            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW\n",
    "        ) / SUM(Total_Sintoma) OVER (PARTITION BY Ano, Mes) AS Pareto_Sintoma_Pct\n",
    "    FROM AGREGADO_SINTOMA\n",
    "),\n",
    "\n",
    "AGREGADO_DEFEITO AS (\n",
    "    SELECT Ano, Mes, Defeito_Estratificado, SUM(Qtd_Defeitos) AS Total_Defeito\n",
    "    FROM REPAROS_FILTRADOS\n",
    "    GROUP BY Ano, Mes, Defeito_Estratificado\n",
    "),\n",
    "PARETO_DEFEITO AS (\n",
    "    SELECT \n",
    "        Ano,\n",
    "        Mes,\n",
    "        Defeito_Estratificado,\n",
    "        ROW_NUMBER() OVER (PARTITION BY Ano, Mes ORDER BY Total_Defeito DESC, Defeito_Estratificado ASC) AS Rank_Defeito,\n",
    "        SUM(Total_Defeito) OVER (\n",
    "            PARTITION BY Ano, Mes\n",
    "            ORDER BY Total_Defeito DESC, Defeito_Estratificado ASC\n",
    "            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW\n",
    "        ) / SUM(Total_Defeito) OVER (PARTITION BY Ano, Mes) AS Pareto_Defeito_Pct\n",
    "    FROM AGREGADO_DEFEITO\n",
    "),\n",
    "\n",
    "AGREGADO_ACAO AS (\n",
    "    SELECT Ano, Mes, Acao_Corretiva, SUM(Qtd_Defeitos) AS Total_Acao\n",
    "    FROM REPAROS_FILTRADOS\n",
    "    GROUP BY Ano, Mes, Acao_Corretiva\n",
    "),\n",
    "PARETO_ACAO AS (\n",
    "    SELECT \n",
    "        Ano,\n",
    "        Mes,\n",
    "        Acao_Corretiva,\n",
    "        ROW_NUMBER() OVER (PARTITION BY Ano, Mes ORDER BY Total_Acao DESC, Acao_Corretiva ASC) AS Rank_Acao,\n",
    "        SUM(Total_Acao) OVER (\n",
    "            PARTITION BY Ano, Mes\n",
    "            ORDER BY Total_Acao DESC, Acao_Corretiva ASC\n",
    "            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW\n",
    "        ) / SUM(Total_Acao) OVER (PARTITION BY Ano, Mes) AS Pareto_AcaoCorretiva_Pct\n",
    "    FROM AGREGADO_ACAO\n",
    "),\n",
    "\n",
    "-- ===== PRODUÇÃO AGREGADA POR PRODUTO/MÊS =====\n",
    "PRODUCAO AS (\n",
    "    SELECT CodProd, Ano, Mes, SUM(Qtd_Produzida) AS Qtd_Produzida\n",
    "    FROM gold.analistas.vw_producaocompletacomapontamento\n",
    "    GROUP BY CodProd, Ano, Mes\n",
    "),\n",
    "\n",
    "-- ===== EXPEDIÇÃO AGREGADA POR PRODUTO/MÊS =====\n",
    "EXPEDIDO AS (\n",
    "    SELECT CodProd, Ano, Mes, SUM(Quantidade) AS QtdExpedida\n",
    "    FROM gold.analistas.vw_superset_expedicaoconsolidada\n",
    "    WHERE Planta = 'CONTAGEM/MG'\n",
    "    GROUP BY CodProd, Ano, Mes\n",
    ")\n",
    "\n",
    "-- 5. Projeção Final — ranking reflete o volume real do dataset filtrado\n",
    "SELECT \n",
    "    'CONTAGEM/MG'                                                       AS Planta,\n",
    "    r.Processo,\n",
    "    r.OrdemProducao                                                     AS OP,\n",
    "    r.Ano, \n",
    "    r.Mes, \n",
    "    r.Semana,\n",
    "    r.Data_Reparo                                                       AS DataProducao,\n",
    "    r.DataHora_Reparo                                                   AS DataHoraApontamento,\n",
    "    \n",
    "    CASE r.Mes\n",
    "        WHEN 1  THEN '01. JANEIRO'   WHEN 2  THEN '02. FEVEREIRO'\n",
    "        WHEN 3  THEN '03. MARÇO'     WHEN 4  THEN '04. ABRIL'\n",
    "        WHEN 5  THEN '05. MAIO'      WHEN 6  THEN '06. JUNHO'\n",
    "        WHEN 7  THEN '07. JULHO'     WHEN 8  THEN '08. AGOSTO'\n",
    "        WHEN 9  THEN '09. SETEMBRO'  WHEN 10 THEN '10. OUTUBRO'\n",
    "        WHEN 11 THEN '11. NOVEMBRO'  WHEN 12 THEN '12. DEZEMBRO'\n",
    "    END AS Mes_Ordenado,\n",
    "\n",
    "    r.CodProd, \n",
    "    sku.DescricaoProduto, \n",
    "    sku.Fornecedor, \n",
    "    sku.Modelo, \n",
    "    sku.Familia,\n",
    "\n",
    "    CASE\n",
    "        WHEN UPPER(sku.DescricaoProduto) RLIKE '(AIO|ALL IN ONE|ALL-IN-ONE)'\n",
    "             OR CAST(sku.CodProduto AS STRING) IN ('96511', '96513', '96514', '96515', '96516', '96518', '96519', '96520', '96521', '96523', '96524', '96525', '96526', '96527', '96528', '96530', '110389', '110390', '110391', '110392', '110393', '110394', '110395', '110398', '110399', '110404', '110405', '110406', '110408', '110409', '110410', '110411', '110414', '110416', '110417', '110418', '110419', '110420', '110421', '110423', '110424', '110425', '110426', '112199', '117263', '131187', '131188', '131366', '131369', '131371', '131372', '131374', '131376', '131377', '131379', '131381', '131382', '131383', '131384', '131385', '131386', '89093', '130974', '131497') THEN 'AIO'\n",
    "        WHEN UPPER(sku.Familia) IN ('DESKTOP', 'DESKTOPS', 'COMPUTADORES') OR UPPER(sku.Familia) LIKE '%DESKTOP%' THEN\n",
    "            CASE\n",
    "                WHEN CAST(sku.CodProduto AS STRING) IN ('72326', '72327', '72328', '72329', '72331', '72351', '72353', '72357', '72861', '72869', '72881', '77323', '77371', '77372', '77373', '77374', '77375', '77377', '77378', '77379', '77380', '77381', '77382', '77383', '77384', '77386', '77387', '77388', '77390', '77392', '77394', '80648', '80650', '80652', '80653', '80654', '80655', '80656', '80657', '80658', '80659', '80660', '80661', '80821', '80825', '80826', '80827', '80828', '80829', '80830', '80831', '80833', '80835', '80836', '85225', '85227', '85228', '85229', '85230', '85236', '85250', '85251', '85256', '85257', '85269', '85271', '85273', '85279', '85280', '85284', '85286', '85287', '85288', '85289', '85292', '85293', '85294', '85305', '85307', '85308', '85309', '85310', '85312', '85314', '85320', '85329', '85331', '89114', '89115', '89117', '89118', '89121', '89124', '89125', '89127', '89130', '89131', '89132', '91084', '91091', '91111', '92608', '92611', '92613', '92614', '92617', '92618', '92619', '92620', '92622', '92623', '92624', '92626', '92627', '92628', '92629', '92630', '92631', '92632', '92633', '92634', '92635', '92636', '92637', '92638', '93757', '93758', '93759', '93760', '93761', '93762', '93763', '93764', '93765', '93766', '93768', '93769', '93770', '93771', '93772', '93773', '93774', '93775', '93776', '93777', '93778', '93779', '93800', '93801', '93802', '93803', '93805', '93808', '93811', '93815', '93818', '93819', '93824', '93831', '93832', '93833', '93834', '104483', '104487', '104489', '104492', '104493', '104494', '104497', '104499', '104506', '104507', '104509', '104511', '104513', '104515', '104525', '104526', '104533', '104534', '104537', '104540', '104541', '104542', '104544', '104545', '104547', '104553', '104554', '104555', '104556', '104607', '104609', '104610', '104612', '104614', '104615', '104619', '104620', '104622', '104623', '104624', '104625', '104626', '104627', '104629', '104630', '104631', '104633', '104634', '104636', '104637', '104639', '104640', '104642', '104643', '104644', '104645', '104647', '104648', '104649', '104650', '104656', '104658', '104659', '104660', '104661', '104662', '104663', '104667', '104668', '104669', '104671', '106249', '106250', '106251', '106253', '106254', '106255', '106256', '106257', '106258', '106259', '106260', '106261', '106262', '106264', '106265', '106266', '106267', '106268', '106269', '106270', '106271', '106272', '106273', '106283', '106616', '106618', '106619', '106620', '106621', '106622', '106623', '106624', '131388', '131391', '131393', '131394', '131397', '131399', '131401', '131404', '131408', '131409', '131410', '131411', '131412', '131413', '131414', '131415', '131416', '131417', '131418', '131419', '131420', '131421', '131422', '131423', '91112', '91113', '91114', '91115', '91117', '91120', '91121', '91122', '91154', '91157', '91159', '91165', '132041', '132042', '132043', '132044', '132045', '132046', '132047', '132048', '132049', '132050', '132051', '132052', '132053', '132054') THEN 'GAMER'\n",
    "                WHEN CAST(sku.CodProduto AS STRING) IN ('72473', '72479', '72480', '72481', '72482', '72483', '72484', '72490', '72491', '72492', '72523', '72524', '72528', '72531', '72532', '72533', '72534', '72542', '72560', '72561', '72562', '72564', '72571', '72572', '72576', '73483', '73484', '73485', '73486', '73513', '73514', '73515', '73516', '73544', '73546', '73548', '73549', '90805', '90806', '90808', '90810', '90811', '90812', '90813', '90814', '90815', '90929', '90931', '90933', '90944', '90946', '90947', '98433', '98434', '98435', '98437', '98438', '98443', '98444', '98445', '98448', '98450', '98452', '98453', '98454', '98457', '98458', '98459', '98460', '98462', '98464', '98465', '98466', '98468', '98469', '98470', '98471', '98473', '98474', '98475', '98476', '98483', '98484', '98485', '98486', '98487', '98488', '98489', '98490', '98492', '98493', '98494', '98495', '98496', '98497', '98499', '98500', '98501', '98502', '98503', '98505', '98506', '98507', '98508', '98509', '98510', '98511', '98513', '98526', '98527', '98528', '98529', '98530', '98531', '98532', '98534', '98535', '98536', '98537', '98538', '98539', '98540', '98541', '98542') THEN 'DESK'\n",
    "                ELSE CASE WHEN UPPER(sku.DescricaoProduto) LIKE '%GAMER%' THEN 'GAMER' WHEN UPPER(sku.DescricaoProduto) LIKE '%SLIM%' THEN 'SLIM' ELSE 'DESK' END\n",
    "            END\n",
    "        ELSE 'OUTROS'\n",
    "    END AS SubgrupoProduto,\n",
    "\n",
    "    r.Qtd_Defeitos,\n",
    "\n",
    "    -- Métricas de volume (produção e expedição do produto/mês) — partição SEM OP (validado: com OP infla proporcional ao nº de OPs)\n",
    "    CASE WHEN ROW_NUMBER() OVER (PARTITION BY r.CodProd, r.Ano, r.Mes ORDER BY r.DataHora_Reparo) = 1\n",
    "         THEN COALESCE(prod.Qtd_Produzida, 0) ELSE 0 END AS Qtd_Produzida,\n",
    "    CASE WHEN ROW_NUMBER() OVER (PARTITION BY r.CodProd, r.Ano, r.Mes ORDER BY r.DataHora_Reparo) = 1\n",
    "         THEN COALESCE(exp.QtdExpedida, 0) ELSE 0 END AS QtdExpedida,\n",
    "\n",
    "    r.Defeito_Estratificado                                             AS Defeito,\n",
    "    r.Sintoma,\n",
    "    r.Acao_Corretiva,\n",
    "    CAST(r.CodPecaTrocada AS STRING)                                    AS CodPecaTrocada,\n",
    "    r.DescricaoPecaTrocada,\n",
    "    r.Serie_PA,\n",
    "    r.Centro_Trabalho_Reparo,\n",
    "\n",
    "    est.CodLocalEstoque,\n",
    "    est.DescricaoLocalEstoque,\n",
    "\n",
    "    -- Métricas do Pareto (calculadas sobre dados filtrados)\n",
    "    ps.Pareto_Sintoma_Pct,\n",
    "    pd.Pareto_Defeito_Pct,\n",
    "    pa.Pareto_AcaoCorretiva_Pct,\n",
    "\n",
    "    -- Top 10 dinâmico (baseado no volume real pós-filtro)\n",
    "    CASE WHEN ps.Rank_Sintoma <= 10 THEN LPAD(CAST(ps.Rank_Sintoma AS STRING), 2, '0') || '. ' || r.Sintoma ELSE '11. OUTROS' END AS Sintoma_Top10,\n",
    "    CASE WHEN pd.Rank_Defeito <= 10 THEN LPAD(CAST(pd.Rank_Defeito AS STRING), 2, '0') || '. ' || r.Defeito_Estratificado ELSE '11. OUTROS' END AS Defeito_Top10,\n",
    "    CASE WHEN pa.Rank_Acao <= 10 THEN LPAD(CAST(pa.Rank_Acao AS STRING), 2, '0') || '. ' || r.Acao_Corretiva ELSE '11. OUTROS' END AS Acao_Top10,\n",
    "\n",
    "    -- Rótulo prefixado para ECharts — agora respeita a ordem real de volume\n",
    "    LPAD(CAST(ps.Rank_Sintoma AS STRING), 2, '0') || '. ' || r.Sintoma AS Sintoma_Ordenado,\n",
    "    LPAD(CAST(pd.Rank_Defeito AS STRING), 2, '0') || '. ' || r.Defeito_Estratificado AS Defeito_Ordenado,\n",
    "    LPAD(CAST(pa.Rank_Acao AS STRING), 2, '0') || '. ' || r.Acao_Corretiva AS Acao_Ordenada\n",
    "\n",
    "FROM REPAROS_FILTRADOS r\n",
    "INNER JOIN SKU_ATRIBUTOS sku \n",
    "    ON r.CodProd = sku.CodProduto\n",
    "LEFT JOIN (\n",
    "    SELECT CodProduto, MAX(CodLocal) AS CodLocalEstoque, MAX(NomeLocal) AS DescricaoLocalEstoque\n",
    "    FROM gold.sankhya.fato_estoque\n",
    "    GROUP BY CodProduto\n",
    ") est ON r.CodProd = est.CodProduto\n",
    "LEFT JOIN PARETO_SINTOMA ps ON r.Ano = ps.Ano AND r.Mes = ps.Mes AND r.Sintoma = ps.Sintoma\n",
    "LEFT JOIN PARETO_DEFEITO pd ON r.Ano = pd.Ano AND r.Mes = pd.Mes AND r.Defeito_Estratificado = pd.Defeito_Estratificado\n",
    "LEFT JOIN PARETO_ACAO pa ON r.Ano = pa.Ano AND r.Mes = pa.Mes AND r.Acao_Corretiva = pa.Acao_Corretiva\n",
    "-- JOINs de volume (produção + expedição)\n",
    "LEFT JOIN PRODUCAO prod ON r.CodProd = prod.CodProd AND r.Ano = prod.Ano AND r.Mes = prod.Mes\n",
    "LEFT JOIN EXPEDIDO exp  ON r.CodProd = exp.CodProd  AND r.Ano = exp.Ano  AND r.Mes = exp.Mes\n",
    "ORDER BY r.Data_Reparo DESC\n",
    ");"
   ]
  }
 ],
